import type { Bucket, FileMetadata } from "@google-cloud/storage";
import { listingPreviewPrefix, listingPreviewVersion } from "./listingPreview";

const dayMs = 86_400_000;
/** Age is measured from the newer of creation and last modification, not access.
 * Current entries eventually expire too: old opaque hashes cannot identify orphans.
 * An expired but still-used preview is regenerated by getListingPreview on demand. */
export const listingPreviewRetentionPolicy = Object.freeze({
  currentDays: 90,
  retiredDays: 30,
  maxDeletes: 100,
  pageSize: 200,
});

export type RetentionDecision = {
  eligible: boolean;
  reason: "current-expired" | "retired-expired" | "grace-period" | "unknown-object" | "unknown-metadata";
};

export function decideListingPreviewRetention(name: string, metadata: FileMetadata, now: number): RetentionDecision {
  const match = /^listing-previews\/listing-v(0|[1-9]\d*)\/[a-f0-9]{64}\.webp$/.exec(name);
  const current = Number(listingPreviewVersion.replace("listing-v", ""));
  const version = match ? Number(match[1]) : NaN;
  // Never guess about foreign objects or future encoders (including rolling deploys).
  if (!Number.isSafeInteger(current) || current < 0 ||
    !Number.isSafeInteger(version) || version > current || metadata.contentType !== "image/webp") {
    return { eligible: false, reason: "unknown-object" };
  }
  const created = Date.parse(metadata.timeCreated ?? "");
  const updated = Date.parse(metadata.updated ?? "");
  if (!Number.isFinite(created) || !Number.isFinite(updated) ||
    !/^[1-9]\d*$/.test(String(metadata.generation ?? "")) ||
    !/^[1-9]\d*$/.test(String(metadata.metageneration ?? ""))) {
    return { eligible: false, reason: "unknown-metadata" };
  }
  const retired = version < current;
  const days = retired ? listingPreviewRetentionPolicy.retiredDays : listingPreviewRetentionPolicy.currentDays;
  const eligible = now - Math.max(created, updated) >= days * dayMs;
  return { eligible, reason: eligible ? retired ? "retired-expired" : "current-expired" : "grace-period" };
}

export type RetentionEntry = {
  bucket: string;
  name: string;
  generation?: string;
  bytes: number;
  reason: string;
  action: "keep" | "would-delete" | "deleted" | "delete-limit" | "changed-or-missing";
};

/** Operator-only maintenance, never exposed as a public HTTP endpoint.
 * Reports first by default. Enumerates ONLY the reserved derivative prefix, in
 * pages. Fresh metadata and generation/metageneration preconditions prevent a
 * concurrent regeneration or metadata update from being removed. No DB access. */
export async function retainListingPreviews(
  buckets: Bucket[],
  options: { apply?: boolean; now?: number; onEntry?: (entry: RetentionEntry) => void } = {},
) {
  const now = options.now ?? Date.now();
  if (!Number.isFinite(now)) throw new Error("Invalid retention clock.");
  const report = {
    mode: options.apply ? "apply" : "dry-run",
    asOf: new Date(now).toISOString(),
    policy: listingPreviewRetentionPolicy,
    scanned: 0, kept: 0, eligible: 0, eligibleBytes: 0,
    deleted: 0, deletedBytes: 0, changedOrMissing: 0, limited: 0,
  };
  let attempts = 0;
  for (const bucket of buckets) {
    let pageToken: string | undefined;
    const seenTokens = new Set<string>();
    do {
      const [files, next] = await bucket.getFiles({
        prefix: listingPreviewPrefix,
        autoPaginate: false,
        maxResults: listingPreviewRetentionPolicy.pageSize,
        ...(pageToken ? { pageToken } : {}),
      });
      for (const file of files) {
        report.scanned++;
        // Defense in depth if the storage listing ever returns an unrelated file.
        if (!/^listing-previews\/listing-v(?:0|[1-9]\d*)\/[a-f0-9]{64}\.webp$/.test(file.name)) {
          report.kept++;
          options.onEntry?.({ bucket: bucket.name, name: file.name, bytes: 0, action: "keep", reason: "unknown-object" });
          continue;
        }
        try {
          const [metadata] = await file.getMetadata();
          const decision = decideListingPreviewRetention(file.name, metadata, now);
          const size = Number(metadata.size);
          const bytes = Number.isFinite(size) && size >= 0 ? size : 0;
          const entry: RetentionEntry = {
            bucket: bucket.name, name: file.name, generation: String(metadata.generation ?? ""),
            bytes, reason: decision.reason, action: "keep",
          };
          if (!decision.eligible) {
            report.kept++;
          } else {
            report.eligible++;
            report.eligibleBytes += bytes;
            entry.action = "would-delete";
            if (options.apply) {
              if (attempts >= listingPreviewRetentionPolicy.maxDeletes) {
                report.limited++;
                entry.action = "delete-limit";
              } else {
                attempts++;
                // Configure preconditions on a NEW handle, never the serving handle.
                await bucket.file(file.name, { preconditionOpts: {
                  ifGenerationMatch: metadata.generation,
                  ifMetagenerationMatch: metadata.metageneration,
                } }).delete();
                report.deleted++;
                report.deletedBytes += bytes;
                entry.action = "deleted";
              }
            }
          }
          options.onEntry?.(entry);
        } catch (error) {
          if (![404, 412].includes(Number((error as { code?: number }).code))) throw error;
          report.changedOrMissing++;
          options.onEntry?.({
            bucket: bucket.name, name: file.name, bytes: 0,
            action: "changed-or-missing", reason: "concurrent-change",
          });
        }
      }
      pageToken = next?.pageToken;
      if (pageToken) {
        if (seenTokens.has(pageToken)) throw new Error("Storage repeated a pagination token; stopping safely.");
        seenTokens.add(pageToken);
      }
    } while (pageToken);
  }
  return report;
}
